;(['es', 'fr', 'de', 'ja', 'pt', 'ru', 'ar'] as const).forEach((language) => {
  settingsPhraseTranslations[language] = {
    ...settingsPhraseTranslations.en,
    ...settingsPhraseTranslations[language],
  }
})

const getValueFromDictionary = (
  dictionary: Partial<Record<Language, Record<string, string>>>,
  locale: Language,
  key: string,
): string | undefined => dictionary[locale]?.[key]

export const getTranslation = (language: Language, key: string): string => {
  const dictionaries: Array<Partial<Record<Language, Record<string, string>>>> = [
    translations,
    profilePhraseTranslations,
    settingsPhraseTranslations,
    footerPhraseTranslations,
    productInventoryPhraseTranslations,
    expensePhraseTranslations,
    transactionPhraseTranslations,
    dashboardPhraseTranslations,
    reportDetailAndPreviewTranslations,
    reportPhraseTranslationOverrides,
    phraseTranslations,
    reportPhraseTranslations,
  ]

  for (const dictionary of dictionaries) {
    const localizedValue = getValueFromDictionary(dictionary, language, key)
    if (localizedValue) return localizedValue
  }

  for (const dictionary of dictionaries) {
    const fallbackValue = getValueFromDictionary(dictionary, 'en', key)
    if (fallbackValue) return fallbackValue
  }

  return key
}

export const getDefaultLanguage = (): Language => {
  const saved = localStorage.getItem('cashflow_language') as Language | null
  if (saved && languages.some((l) => l.code === saved)) {
    return saved
  }
  return 'en'
}

export const setLanguage = (language: Language) => {
  localStorage.setItem('cashflow_language', language)
}
